  // if (isWriting) {
  //   renderJustifiedText(q.content, 16, 50, display.width() - 32);
  // } else {
  //   renderLeftAlignedText(q.content, 16, 50, display.width() - 32);
  // }

  // display.setTextColor(sharedAccent);
