  color: #ffffff;
  margin: auto 0;
  padding: 4px 0;
  word-break: break-word;
}
.ep-content.content-justify {
  text-align: justify !important;
  text-justify: inter-word !important;
  hyphens: auto;
}
.ep-content.content-left {
  text-align: left !important;
}

/* Architectural Quotation Marks */
.ep-qmark {
  font-family: Georgia, "IBM Plex Serif", serif !important;
  font-style: normal !important;
  font-weight: 700;
  font-size: 1.45em;
  line-height: 0;
  display: inline-block;
  user-select: none;
}
.ep-qmark-open { margin-right: 3px; vertical-align: -0.08em; }
.ep-qmark-close { margin-left: 3px; vertical-align: -0.2em; }

/* Personal Context Box (Callout) */
.ep-context {
  font-size: 10.5px;
  padding: 6px 8px;
  margin-top: 8px;
  line-height: 1.45;
  background: rgba(255, 255, 255, 0.04);
  border-left: 2px solid #555555;
  color: #888888;
  border-radius: 0 4px 4px 0;
}

/* Tactile Hardware Beeper Button Bar (Physical Chassis Controls) */
.beeper-hw-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px dashed #262626;

