      // Tags Blocks
      const tagsBlocks = b.hashtagThemes.map((t, idx) => {
        const tagStyle = generateTagColorStyle(t, idx);
        return `<span class="ep-tag-block" style="${tagStyle}">${t}</span>`;
      }).join('');

      // Container Name
      const containerHTML = `<span class="ep-container-name" style="color:${sharedAccentColor};">${b.containerName}</span>`;

      // Render Screen with FIXED HEADER + SCROLLABLE VIEWPORT + FIXED FOOTER
      screen.innerHTML = `
        <!-- ZONE 1: FIXED HARDWARE HEADER -->
        <div class="ep-status-bar">
          <div>${headerTitleHTML}</div>
          <div>${headerDateHTML}</div>
        </div>

        <!-- ZONE 2 & 3: SCROLLABLE VIEWPORT (ZERO-CRAM CORE) -->
        <div class="ep-viewport" id="ep-viewport" onscroll="updateScrollTelemetry()">
          <div class="ep-content ${alignClass}">
            ${formattedContent}
          </div>

          ${(showContext && b.context) ? `
            <div class="ep-context">
              ${b.context}
            </div>
          ` : ''}
        </div>

        <!-- ZONE 4: FIXED HARDWARE FOOTER -->
        <div class="ep-footer">
          <div class="ep-tags">${tagsBlocks}</div>
          <div class="ep-attribution">${containerHTML}</div>
        </div>
      `;

      // Reset scroll position and update telemetry
      const vp = document.getElementById('ep-viewport');
      if (vp) {
        vp.scrollTop = 0;
        setTimeout(updateScrollTelemetry, 50);
      }
    }

    // Keyboard Shortcuts (Arrow keys & Space for tactile scrolling)
    window.addEventListener('keydown', (e) => {
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;
      if (e.key === 'ArrowUp') { scrollViewport(-40); e.preventDefault(); }
      if (e.key === 'ArrowDown') { scrollViewport(40); e.preventDefault(); }
      if (e.key === 'PageUp') { scrollViewport(-140); e.preventDefault(); }
      if (e.key === 'PageDown' || e.key === ' ') { scrollViewport(140); e.preventDefault(); }
      if (e.key === 'ArrowLeft') { navQuote(-1); e.preventDefault(); }
      if (e.key === 'ArrowRight') { navQuote(1); e.preventDefault(); }
    });

    window.addEventListener('DOMContentLoaded', init);
  </script>
</body>
</html>

