.ep-viewport {
  flex: 1;
  min-height: 0;
  overflow-y: hidden; /* No free-form scrollbar */
  overflow-x: hidden;
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* IE 10+ */
  position: relative;
}
.ep-viewport::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

