917	
918	    function loadSelectedQuote(qid) {
919	      activeQuote = quotesList.find(q => q.id === qid) || quotesList[0];
920	      if (!activeQuote) return;
921	
922	      document.getElementById('quote-select').value = activeQuote.id;
923	      playBeeperChirp('chirp');
924	      renderActivePrescript();
925	    }
926	
927	    function navQuote(step) {
928	      if (quotesList.length === 0) return;
929	      const curIdx = quotesList.findIndex(q => q.id === (activeQuote ? activeQuote.id : ''));
930	      let nextIdx = (curIdx + step + quotesList.length) % quotesList.length;
931	      loadSelectedQuote(quotesList[nextIdx].id);
932	    }
933	
934	    function pickRandomQuote() {
935	      if (quotesList.length === 0) return;
936	      const rnd = quotesList[Math.floor(Math.random() * quotesList.length)];
937	      loadSelectedQuote(rnd.id);
938	    }
939	
