// ==============================================================================
// 5. VIEWPORT 4-LINE DISCRETE PAGINATION ENGINE (ZERO SCROLLBAR // 4 LINES MAX)
// ==============================================================================
let currentPage = 1;
let totalPages = 1;
let wheelDebounceTimer = null;

function getCharsPerLine(key) {
  const p = HARDWARE_PRESETS[key] || HARDWARE_PRESETS['19'];
  // Target width minus 28px padding divided by ~7.9px monospace character width
  return Math.max(16, Math.floor((p.w - 28) / 7.9));
}

function wrapTextToLines(text, maxChars) {
  const paragraphs = (text || "").split('\n');
  const lines = [];

  for (const para of paragraphs) {
    if (!para.trim()) {
      lines.push('');
      continue;
    }
    const words = para.trim().split(/\s+/);
    let curLine = '';
    for (const w of words) {
      if (!curLine) {
        curLine = w;
      } else if ((curLine + ' ' + w).length <= maxChars) {
        curLine += ' ' + w;
      } else {
        lines.push(curLine);
        curLine = w;
      }
    }
    if (curLine) {
      lines.push(curLine);
    }
  }
  return lines;
}

// Splits quote & context into discrete pages of AT MOST 4 LINES each
function buildPrescriptPages(bundle, maxChars, accentColor) {
  const rawQuoteLines = wrapTextToLines(bundle.content, maxChars);
  const pages = [];
  const MAX_LINES = 4;

  // 1. Chunk quote lines into 4-line pages
  const rawQuotePages = [];
  for (let i = 0; i < rawQuoteLines.length; i += MAX_LINES) {
    rawQuotePages.push(rawQuoteLines.slice(i, i + MAX_LINES));
  }
  if (rawQuotePages.length === 0) rawQuotePages.push(['']);

  const totalQuotePages = rawQuotePages.length;

  rawQuotePages.forEach((lines, pIdx) => {
    const isFirst = (pIdx === 0);
    const isLastQuotePage = (pIdx === totalQuotePages - 1);
    const decoratedLines = lines.map(l => l);

    // Decorate opening quote on page 1
    if (isFirst && decoratedLines.length > 0) {
      decoratedLines[0] = `<span class="ep-qmark ep-qmark-open" style="color:${accentColor};">“</span>${decoratedLines[0]}`;
    } else if (!isFirst && decoratedLines.length > 0) {
      decoratedLines[0] = `<span class="ep-ellipsis-cue" style="color:${accentColor};">... </span>${decoratedLines[0]}`;
    }

    // Decorate line 4 (or end of page)
    const lastLineIdx = decoratedLines.length - 1;
    if (!isLastQuotePage) {
      // Quote continues onto next page: indicate with "..."
      decoratedLines[lastLineIdx] = `${decoratedLines[lastLineIdx]}<span class="ep-ellipsis-cue" style="color:${accentColor};">...</span>`;
    } else {
      // Quote finishes on this page: append closing quote
      decoratedLines[lastLineIdx] = `${decoratedLines[lastLineIdx]}<span class="ep-qmark ep-qmark-close" style="color:${accentColor};">”</span>`;
    }

    pages.push({
      type: 'quote',
      lines: decoratedLines,
      hasNext: !isLastQuotePage
    });
  });

  // 2. Chunk optional context into 4-line pages if enabled
  if (showContext && bundle.context && bundle.context.trim()) {
    const rawCtxLines = wrapTextToLines(`[Note] ${bundle.context.trim()}`, maxChars);
    for (let i = 0; i < rawCtxLines.length; i += MAX_LINES) {
      const cLines = rawCtxLines.slice(i, i + MAX_LINES);
      const isLastCtxPage = (i + MAX_LINES >= rawCtxLines.length);
      if (!isLastCtxPage && cLines.length > 0) {
        cLines[cLines.length - 1] = `${cLines[cLines.length - 1]}<span class="ep-ellipsis-cue" style="color:${accentColor};">...</span>`;
      }
      pages.push({
        type: 'context',
        lines: cLines,
        hasNext: !isLastCtxPage
      });
    }
  }

  return pages.length > 0 ? pages : [{ type: 'quote', lines: [''], hasNext: false }];
}

function updateTelemetryControls() {
  const pageLabel = document.getElementById('page-pos-label');
  const prevBtn = document.getElementById('btn-page-prev');
  const nextBtn = document.getElementById('btn-page-next');

  if (pageLabel) {
    if (totalPages > 1) {
      pageLabel.textContent = `Page ${currentPage} of ${totalPages} ···`;
    } else {
      pageLabel.textContent = `Page 1 of 1 (Complete)`;
    }
  }
  if (prevBtn) prevBtn.style.opacity = (currentPage <= 1) ? '0.4' : '1';
  if (nextBtn) nextBtn.style.opacity = (currentPage >= totalPages) ? '0.4' : '1';
}

function changePage(direction) {
  const target = currentPage + direction;
  if (target >= 1 && target <= totalPages) {
    currentPage = target;
    playBeeperChirp('click');
    renderActivePrescript();
  }
}

function goToPage(pageNum) {
  if (pageNum === 999) pageNum = totalPages;
  if (pageNum >= 1 && pageNum <= totalPages) {
    currentPage = pageNum;
    playBeeperChirp('click');
    renderActivePrescript();
  }
}

function toggleAutoScroll() {
  const btn = document.getElementById('btn-autoscroll');
  if (autoScrollInterval) {
    clearInterval(autoScrollInterval);
    autoScrollInterval = null;
    btn.textContent = 'Auto-Page: OFF';
    btn.classList.remove('active');
  } else {
    btn.textContent = 'Auto-Page: ON';
    btn.classList.add('active');
    autoScrollInterval = setInterval(() => {
      if (currentPage < totalPages) {
        changePage(1);
      } else {
        currentPage = 1;
        playBeeperChirp('click');
        renderActivePrescript();
      }
    }, 4200);
  }
}

