// ==============================================================================
// 5. VIEWPORT 4-LINE DISCRETE PAGINATION ENGINE (ZERO SCROLLBAR // 4 LINES MAX)
// ==============================================================================
let currentPage = 1;
let totalPages = 1;
let wheelDebounceTimer = null;

function getCharsPerLine(key) {
  const p = HARDWARE_PRESETS[key] || HARDWARE_PRESETS['19'];
  const f = FONT_PRESETS[currentFontKey] || FONT_PRESETS['jetbrains'];
  // Target width minus 28px padding divided by font character ratio
  return Math.max(16, Math.floor((p.w - 28) / (f.charRatio || 7.9)));
}

function wrapTextToLines(text, maxChars) {
  const paragraphs = (text || "").split('\n');
  const lines = [];

  for (const para of paragraphs) {
    if (!para.trim()) {
      lines.push('');
      continue;
    }
    const words = para.trim().split(/\s+/);
    let curLine = '';
    for (const w of words) {
      if (!curLine) {
        curLine = w;
      } else if ((curLine + ' ' + w).length <= maxChars) {
        curLine += ' ' + w;
      } else {
        lines.push(curLine);
        curLine = w;
      }
    }
    if (curLine) {
      lines.push(curLine);
    }
  }
  return lines;
}

// Splits quote & context into discrete pages of AT MOST 4 LINES each
function buildPrescriptPages(bundle, maxChars, accentColor) {
  const rawQuoteLines = wrapTextToLines(bundle.content, maxChars);
  const pages = [];
  const MAX_LINES = 4;

  // 1. Chunk quote lines into 4-line pages
  const rawQuotePages = [];
  for (let i = 0; i < rawQuoteLines.length; i += MAX_LINES) {
    rawQuotePages.push(rawQuoteLines.slice(i, i + MAX_LINES));
  }
  if (rawQuotePages.length === 0) rawQuotePages.push(['']);

  const totalQuotePages = rawQuotePages.length;

  rawQuotePages.forEach((lines, pIdx) => {
    const isFirst = (pIdx === 0);
    const isLastQuotePage = (pIdx === totalQuotePages - 1);
    const decoratedLines = lines.map(l => l);

    // Decorate opening quote on page 1
    if (isFirst && decoratedLines.length > 0) {
      decoratedLines[0] = `<span class="ep-qmark ep-qmark-open" style="color:${accentColor};">“</span>${decoratedLines[0]}`;
    } else if (!isFirst && decoratedLines.length > 0) {
      decoratedLines[0] = `<span class="ep-ellipsis-cue" style="color:${accentColor};">... </span>${decoratedLines[0]}`;
    }

    // Decorate line 4 (or end of page)
    const lastLineIdx = decoratedLines.length - 1;
    if (!isLastQuotePage) {
      // Quote continues onto next page: indicate with "..."
      decoratedLines[lastLineIdx] = `${decoratedLines[lastLineIdx]}<span class="ep-ellipsis-cue" style="color:${accentColor};">...</span>`;
    } else {
      // Quote finishes on this page: append closing quote
      decoratedLines[lastLineIdx] = `${decoratedLines[lastLineIdx]}<span class="ep-qmark ep-qmark-close" style="color:${accentColor};">”</span>`;
    }

    pages.push({
      type: 'quote',
      lines: decoratedLines,
      hasNext: !isLastQuotePage
    });
  });

