    plain = lineHtml.substring(prefixOpenMatch[0].length);
  }
  const suffixCloseMatch = lineHtml.match(/<span class="ep-qmark ep-qmark-close"[^>]*>”<\/span>/);
  if (suffixCloseMatch) {
    suffixHtml = suffixCloseMatch[0];
    plain = lineHtml.substring(0, lineHtml.length - suffixCloseMatch[0].length);
  }
  const suffixEllipsisMatch = lineHtml.match(/<span class="ep-ellipsis-cue"[^>]*>...<\/span>/);
  if (suffixEllipsisMatch) {
    suffixHtml = suffixEllipsisMatch[0];
    plain = lineHtml.substring(0, lineHtml.length - suffixEllipsisMatch[0].length);
  }
  return { prefixHtml, plainText: plain, suffixHtml };
}
