let soundEnabled = true;

const FONT_PRESETS = {
  "jetbrains": { name: "JetBrains Mono", css: '"JetBrains Mono", monospace', charRatio: 7.9, size: "13px" },
  "ibmplex":   { name: "IBM Plex Mono", css: '"IBM Plex Mono", monospace', charRatio: 7.9, size: "13px" },
  "spacemono": { name: "Space Mono", css: '"Space Mono", monospace', charRatio: 8.2, size: "12.5px" },
  "firacode":  { name: "Fira Code", css: '"Fira Code", monospace', charRatio: 7.9, size: "13px" },
  "vt323":     { name: "VT323 Matrix", css: '"VT323", monospace', charRatio: 6.8, size: "16px" },
  "crimson":   { name: "Crimson Pro", css: '"Crimson Pro", Georgia, serif', charRatio: 7.3, size: "14.5px" },
  "sharetech": { name: "Share Tech Mono", css: '"Share Tech Mono", monospace', charRatio: 7.8, size: "13.5px" }
};

// Web Audio Synthesizer (Zero-Asset 8-bit Pager Chirp)
let audioCtx = null;
function playBeeperChirp(type = 'chirp') {
  if (!soundEnabled) return;
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();

    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);

    const now = audioCtx.currentTime;
    if (type === 'chirp') {
      osc.type = 'square';
      osc.frequency.setValueAtTime(1760, now); // A6
      osc.frequency.setValueAtTime(2637, now + 0.04); // E7
      gain.gain.setValueAtTime(0.04, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
      osc.start(now);
      osc.stop(now + 0.1);
    } else if (type === 'click') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(987, now);
      gain.gain.setValueAtTime(0.03, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);
      osc.start(now);
      osc.stop(now + 0.03);
    }
  } catch (e) {
    // AudioContext silent fallback
  }
}

function toggleSound() {
  soundEnabled = !soundEnabled;
  const btn = document.getElementById('btn-sound');
  btn.textContent = soundEnabled ? '🔔 Sound: ON' : '🔕 Sound: OFF';
  btn.classList.toggle('active', soundEnabled);
  if (soundEnabled) playBeeperChirp('chirp');
}

