const soundDraw = new Audio('audio/draw_sound.wav');
const soundComplete = new Audio('audio/complete_sound.wav');

let audioCtx = null;
function playBeeperChirp(type = 'chirp') {
  if (!soundEnabled) return;
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();

    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);

    const now = audioCtx.currentTime;
    if (type === 'chirp') {
      osc.type = 'square';
      osc.frequency.setValueAtTime(1760, now);
      osc.frequency.setValueAtTime(2637, now + 0.04);
      gain.gain.setValueAtTime(0.04, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
      osc.start(now);
      osc.stop(now + 0.1);
    } else if (type === 'click') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(987, now);
      gain.gain.setValueAtTime(0.03, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);
      osc.start(now);
      osc.stop(now + 0.03);
    }
  } catch (e) {
    // AudioContext silent fallback
  }
}

function playSoundEffect(type) {
  if (!soundEnabled) return;
  try {
    if (type === 'draw') {
      soundDraw.currentTime = 0;
      const p = soundDraw.play();
      if (p && p.catch) p.catch(() => playBeeperChirp('chirp'));
    } else if (type === 'complete') {
      soundComplete.currentTime = 0;
      const p = soundComplete.play();
      if (p && p.catch) p.catch(() => playBeeperChirp('click'));
    }
  } catch (e) {
    playBeeperChirp(type === 'draw' ? 'chirp' : 'click');
  }
}

function toggleSound() {
  soundEnabled = !soundEnabled;
  const btn = document.getElementById('btn-sound');
  btn.textContent = soundEnabled ? '🔔 Sound: ON' : '🔕 Sound: OFF';
  btn.classList.toggle('active', soundEnabled);
  if (soundEnabled) playSoundEffect('complete');
}

// ==============================================================================
// PRESCRIPT TEXT ANIMATION ENGINE
// ==============================================================================
let animationEnabled = true;
let isDrawing = false;
let typingTimer = null;
let lastRenderedPageData = null;
let lastRenderedAlignClass = 'content-left';

function toggleAnimation() {
  animationEnabled = !animationEnabled;
  const btn = document.getElementById('btn-anim');
  if (btn) {
    btn.textContent = animationEnabled ? '📜 Anim: ON' : '⚡ Anim: OFF';
    btn.classList.toggle('active', animationEnabled);
  }
  playSoundEffect('complete');
}

function stopDrawingAnimation() {
  if (typingTimer) {
    clearTimeout(typingTimer);
    typingTimer = null;
  }
  isDrawing = false;
  const led = document.querySelector('.beeper-led');
  if (led) led.classList.remove('drawing');
}

function parseDecoratedLine(lineHtml) {
  let prefix = '';
  let suffix = '';
  let text = lineHtml;

  const openTag = text.match(/^(<span class="ep-qmark ep-qmark-open"[^>]*>“<\/span>)/);
  if (openTag) {
    prefix = openTag[1];
    text = text.substring(openTag[0].length);
  }

  const closeTag = text.match(/(<span class="ep-qmark ep-qmark-close"[^>]*>”<\/span>|<span class="ep-ellipsis-cue"[^>]*>\.\.\.<\/span>)$/);
  if (closeTag) {
    suffix = closeTag[1];
    text = text.substring(0, text.length - closeTag[0].length);
  }

  return { prefix, text, suffix };
}

function runPrescriptTypewriter(activePage, alignClass) {
  stopDrawingAnimation();
  const container = document.getElementById('ep-viewport');
  if (!container) return;

  const parsed = activePage.lines.map(parseDecoratedLine);
  container.innerHTML = `
    <div class="ep-content ${alignClass}">
      ${parsed.map((_, i) => `<div class="ep-text-line" id="ptl-${i}"></div>`).join('')}
    </div>
  `;

  let curL = 0;
  let curC = 0;
  isDrawing = true;
  const led = document.querySelector('.beeper-led');
  if (led) led.classList.add('drawing');

  function typeStep() {
    if (!isDrawing) return;

    if (curL >= parsed.length) {
      isDrawing = false;
      if (led) led.classList.remove('drawing');
      parsed.forEach((pl, idx) => {
        const el = document.getElementById(`ptl-${idx}`);
        if (el) el.innerHTML = `${pl.prefix}${pl.text}${pl.suffix}`;
      });
      return;
    }

    const lineObj = parsed[curL];
    const el = document.getElementById(`ptl-${curL}`);

    if (curC < lineObj.text.length) {
      curC++;
      const currentSub = lineObj.text.substring(0, curC);
      if (el) el.innerHTML = `${lineObj.prefix}${currentSub}<span class="ep-cursor"></span>`;
      typingTimer = setTimeout(typeStep, 9);
    } else {
      if (el) el.innerHTML = `${lineObj.prefix}${lineObj.text}${lineObj.suffix}`;
      curL++;
      curC = 0;
      typingTimer = setTimeout(typeStep, 28);
    }
  }

  typeStep();
}

function skipAnimation() {
  if (!isDrawing) return;
  stopDrawingAnimation();
  const container = document.getElementById('ep-viewport');
  if (container && lastRenderedPageData) {
    container.innerHTML = `
      <div class="ep-content ${lastRenderedAlignClass}">
        ${lastRenderedPageData.lines.map(line => `<div class="ep-text-line">${line}</div>`).join('')}
      </div>
    `;
  }
}

