// AUDIO ENGINE (PRESCRIPTGAME WAV AUDIO + WEBAUDIO SYNTHESIZER FALLBACK)
// ==============================================================================
const soundDraw = new Audio('audio/draw_sound.wav');
const soundComplete = new Audio('audio/complete_sound.wav');

let audioCtx = null;
function playBeeperChirp(type = 'chirp') {
  if (!soundEnabled) return;
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();

    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);

    const now = audioCtx.currentTime;
    if (type === 'chirp') {
      osc.type = 'square';
      osc.frequency.setValueAtTime(1760, now);
      osc.frequency.setValueAtTime(2637, now + 0.04);
      gain.gain.setValueAtTime(0.04, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
      osc.start(now);
      osc.stop(now + 0.1);
    } else if (type === 'click') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(987, now);
      gain.gain.setValueAtTime(0.03, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);
      osc.start(now);
      osc.stop(now + 0.03);
    }
  } catch (e) {
    // AudioContext silent fallback
  }
}

function playSoundEffect(type) {
  if (!soundEnabled) return;
  try {
    if (type === 'draw') {
      soundDraw.currentTime = 0;
      const p = soundDraw.play();
      if (p && p.catch) p.catch(() => playBeeperChirp('chirp'));
    } else if (type === 'complete') {
      soundComplete.currentTime = 0;
      const p = soundComplete.play();
      if (p && p.catch) p.catch(() => playBeeperChirp('click'));
    }
  } catch (e) {
    playBeeperChirp(type === 'draw' ? 'chirp' : 'click');
  }
}

function toggleSound() {
