1195	    function wrapTextToLines(text, maxChars) {
1196	      const paragraphs = (text || "").split('\n');
1197	      const lines = [];
1198	
1199	      for (const para of paragraphs) {
1200	        if (!para.trim()) {
1201	          lines.push('');
1202	          continue;
1203	        }
1204	        const words = para.trim().split(/\s+/);
1205	        let curLine = '';
1206	        for (const w of words) {
1207	          if (!curLine) {
1208	            curLine = w;
1209	          } else if ((curLine + ' ' + w).length <= maxChars) {
1210	            curLine += ' ' + w;
1211	          } else {
1212	            lines.push(curLine);
1213	            curLine = w;
1214	          }
1215	        }
1216	        if (curLine) {
1217	          lines.push(curLine);
1218	        }
1219	      }
1220	      return lines;
1221	    }
