1223	    // Splits quote & context into discrete pages of AT MOST 4 LINES each with strict line budgeting
1224	    function buildPrescriptPages(bundle, maxChars, accentColor) {
1225	      const content = (bundle.content || "").trim();
1226	      const pages = [];
1227	      const MAX_LINES = 4;
1228	
1229	      if (!content) return [{ type: 'quote', lines: [''], hasNext: false }];
1230	
1231	      // Tokenize by paragraphs first to honor explicit line breaks (\n)
1232	      const paragraphs = content.split('\n');
1233	      const tokens = [];
1234	      for (let i = 0; i < paragraphs.length; i++) {
1235	        const pText = paragraphs[i].trim();
1236	        if (pText) {
1237	          const words = pText.split(/\s+/);
1238	          for (const w of words) tokens.push(w);
1239	        }
1240	        if (i < paragraphs.length - 1) {
1241	          tokens.push('\n');
1242	        }
1243	      }
1244	
1245	      let tokenIdx = 0;
1246	      let pageNum = 0;
1247	
1248	      while (tokenIdx < tokens.length) {
1249	        pageNum++;
1250	        const isFirstPage = (pageNum === 1);
1251	        const pageLines = [];
1252	
1253	        for (let lineNum = 1; lineNum <= MAX_LINES && tokenIdx < tokens.length; lineNum++) {
1254	          const isLine4 = (lineNum === MAX_LINES);
1255	
1256	          // Budget characters for this line so "..." never overflows
1257	          let lineBudget = maxChars;
1258	          if (isFirstPage && lineNum === 1) {
1259	            lineBudget = maxChars - 1; // reserve space for “
1260	          }
1261	          if (isLine4) {
1262	            lineBudget = maxChars - 4; // reserve space for ... so it stays on line 4
1263	          }
1264	
1265	          let curLine = '';
1266	          while (tokenIdx < tokens.length) {
1267	            const nextTok = tokens[tokenIdx];
1268	            if (nextTok === '\n') {
1269	              tokenIdx++;
1270	              break;
1271	            }
1272	            if (!curLine) {
1273	              curLine = nextTok;
1274	              tokenIdx++;
1275	            } else if ((curLine + ' ' + nextTok).length <= lineBudget) {
1276	              curLine += ' ' + nextTok;
1277	              tokenIdx++;
1278	            } else {
1279	              break;
1280	            }
1281	          }
1282	
1283	          pageLines.push(curLine);
1284	        }
1285	
1286	        // Lookahead to check if real words remain
1287	        let lookAheadIdx = tokenIdx;
1288	        while (lookAheadIdx < tokens.length && tokens[lookAheadIdx] === '\n') {
1289	          lookAheadIdx++;
1290	        }
1291	        const hasMoreQuote = (lookAheadIdx < tokens.length);
1292	
1293	        // Decorate lines:
1294	        if (isFirstPage && pageLines.length > 0) {
1295	          pageLines[0] = `<span class="ep-qmark ep-qmark-open" style="color:${accentColor};">“</span>${pageLines[0]}`;
1296	        }
1297	
1298	        const lastLineIdx = pageLines.length - 1;
1299	        if (hasMoreQuote) {
1300	          // Quote continues: append "..." directly to line 4 (never wraps)
1301	          pageLines[lastLineIdx] = `${pageLines[lastLineIdx]}<span class="ep-ellipsis-cue" style="color:${accentColor};">...</span>`;
1302	        } else {
1303	          // Quote completes on this page: append closing quotation mark
1304	          pageLines[lastLineIdx] = `${pageLines[lastLineIdx]}<span class="ep-qmark ep-qmark-close" style="color:${accentColor};">”</span>`;
1305	        }
1306	
1307	        pages.push({
1308	          type: 'quote',
1309	          lines: pageLines,
1310	          hasNext: hasMoreQuote
1311	        });
1312	      }
1313	
1314	      // Handle optional context if enabled (also capped at 4 lines max)
1315	      if (showContext && bundle.context && bundle.context.trim()) {
1316	        const ctxWords = bundle.context.trim().split(/\s+/);
1317	        let cIdx = 0;
1318	        let isFirstCtx = true;
1319	
1320	        while (cIdx < ctxWords.length) {
1321	          const cLines = [];
1322	          for (let l = 1; l <= MAX_LINES && cIdx < ctxWords.length; l++) {
1323	            const isL4 = (l === MAX_LINES);
1324	            const lBudget = isL4 ? maxChars - 4 : maxChars;
1325	            let cLine = (isFirstCtx && l === 1) ? '[Note] ' : '';
1326	            if (isFirstCtx && l === 1) isFirstCtx = false;
1327	
1328	            while (cIdx < ctxWords.length) {
1329	              const cw = ctxWords[cIdx];
1330	              if (!cLine) {
1331	                cLine = cw;
1332	                cIdx++;
1333	              } else if ((cLine + ' ' + cw).length <= lBudget) {
1334	                cLine += ' ' + cw;
1335	                cIdx++;
1336	              } else {
1337	                break;
1338	              }
1339	            }
1340	            cLines.push(cLine);
1341	          }
1342	
1343	          const hasMoreCtx = (cIdx < ctxWords.length);
1344	          if (hasMoreCtx && cLines.length > 0) {
1345	            cLines[cLines.length - 1] = `${cLines[cLines.length - 1]}<span class="ep-ellipsis-cue" style="color:${accentColor};">...</span>`;
1346	          }
1347	
1348	          pages.push({
1349	            type: 'context',
1350	            lines: cLines,
1351	            hasNext: hasMoreCtx
1352	          });
1353	        }
1354	      }
1355	
1356	      return pages.length > 0 ? pages : [{ type: 'quote', lines: [''], hasNext: false }];
1357	    }
