851	    function playBeeperChirp(type = 'chirp') {
852	      if (!soundEnabled || !userHasInteracted) return;
853	      try {
854	        if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
855	        if (audioCtx.state === 'suspended') {
856	          audioCtx.resume().catch(() => {});
857	          return;
858	        }
859	
860	        const osc = audioCtx.createOscillator();
861	        const gain = audioCtx.createGain();
862	        osc.connect(gain);
863	        gain.connect(audioCtx.destination);
864	
865	        const now = audioCtx.currentTime;
866	        if (type === 'chirp') {
867	          osc.type = 'square';
868	          osc.frequency.setValueAtTime(1760, now);
869	          osc.frequency.setValueAtTime(2637, now + 0.04);
870	          gain.gain.setValueAtTime(0.04, now);
871	          gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
872	          osc.start(now);
873	          osc.stop(now + 0.1);
874	        } else if (type === 'click') {
875	          osc.type = 'triangle';
876	          osc.frequency.setValueAtTime(987, now);
877	          gain.gain.setValueAtTime(0.03, now);
878	          gain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);
879	          osc.start(now);
880	          osc.stop(now + 0.03);
881	        }
882	      } catch (e) {
