/* Teleprinter Prescript Cursor */
.ep-cursor {
  display: inline-block;
  width: 6.5px;
  height: 1.15em;
  background: var(--accent-cyan);
  vertical-align: -0.16em;
  margin-left: 2px;
  animation: blink-cursor 0.55s infinite;
}
@keyframes blink-cursor {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

/* Architectural Quotation Marks */
.ep-qmark {
  font-family: Georgia, "IBM Plex Serif", serif !important;
  font-style: normal !important;
  font-weight: 700;
  font-size: 1.45em;
  line-height: 0;
  display: inline-block;

