/* Speed Slider Widget */
.speed-slider-wrap {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  background: var(--bg-card);
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-sm);
  padding: 0.22rem 0.65rem;
  font-size: 0.72rem;
}
.speed-slider-wrap input[type=range] {
  -webkit-appearance: none;
  appearance: none;
  width: 95px;
  height: 4px;
  background: #262626;
  border-radius: 2px;
  outline: none;
  cursor: pointer;
}
.speed-slider-wrap input[type=range]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--accent-cyan);
  box-shadow: 0 0 6px var(--accent-cyan);
  cursor: pointer;
  transition: transform 0.1s ease;
}
.speed-slider-wrap input[type=range]::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}
.speed-slider-wrap input[type=range]::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border: none;
  border-radius: 50%;
  background: var(--accent-cyan);
  box-shadow: 0 0 6px var(--accent-cyan);
  cursor: pointer;
}

