let animationEnabled = true;
let isDrawing = false;
let typingTimer = null;
let lastRenderedPageData = null;
let lastRenderedAlignClass = 'content-left';
let lastFinalHeaderTitleHTML = '';

const TYPING_SPEED_PRESETS = [
  { name: '38ms (Prescript)', delay: 38 },
  { name: '55ms (Oracle Slow)', delay: 55 },
  { name: '22ms (Fast Print)', delay: 22 }
];
let currentSpeedIdx = 0;

function cycleTypingSpeed() {
  currentSpeedIdx = (currentSpeedIdx + 1) % TYPING_SPEED_PRESETS.length;
  const sp = TYPING_SPEED_PRESETS[currentSpeedIdx];
