  if (btn) {
    btn.textContent = animationEnabled ? '📜 Anim: ON' : '⚡ Anim: OFF';
    btn.classList.toggle('active', animationEnabled);
  }
  playSoundEffect('complete');
}

function stopDrawingAnimation() {
  if (typingTimer) {
    clearTimeout(typingTimer);
    typingTimer = null;
  }
  isDrawing = false;
  const led = document.querySelector('.beeper-led');
  if (led) led.classList.remove('drawing');
}

function parseDecoratedLine(lineItem) {
  const rawHtml = (typeof lineItem === 'object' && lineItem !== null) ? lineItem.html : lineItem;
  const align = (typeof lineItem === 'object' && lineItem !== null) ? (lineItem.align || 'line-left') : 'line-left';
  let prefix = '';
  let suffix = '';
  let text = rawHtml || '';

  const openTag = text.match(/^(<span class="ep-qmark ep-qmark-open"[^>]*>“<\/span>)/);
  if (openTag) {
    prefix = openTag[1];
    text = text.substring(openTag[0].length);
  }

  const closeTag = text.match(/(<span class="ep-qmark ep-qmark-close"[^>]*>”<\/span>|<span class="ep-ellipsis-cue"[^>]*>\.\.\.<\/span>)$/);
  if (closeTag) {
    suffix = closeTag[1];
    text = text.substring(0, text.length - closeTag[0].length);
  }

  return { prefix, text, suffix, align };
}

function runPrescriptTypewriter(activePage, alignClass) {
  stopDrawingAnimation();
  const container = document.getElementById('ep-viewport');
  if (!container) return;

  const headerTitleEl = document.getElementById('ep-header-left-title');
  if (headerTitleEl) {
    headerTitleEl.innerHTML = `<span class="ep-transmitting-badge">📡 // RECEIVING DIRECTIVE //</span>`;
  }

  const parsed = activePage.lines.map(parseDecoratedLine);
  container.innerHTML = `
    <div class="ep-content ${alignClass}">
      ${parsed.map((pl, i) => `<div class="ep-text-line ${pl.align}" id="ptl-${i}"></div>`).join('')}
    </div>
  `;

  let curL = 0;
  let curC = 0;
  isDrawing = true;
  const led = document.querySelector('.beeper-led');
  if (led) led.classList.add('drawing');

  function typeStep() {
    if (!isDrawing) return;

    if (curL >= parsed.length) {
      isDrawing = false;
      if (led) led.classList.remove('drawing');
      parsed.forEach((pl, idx) => {
        const el = document.getElementById(`ptl-${idx}`);
        if (el) el.innerHTML = `${pl.prefix}${pl.text}${pl.suffix}`;
      });
      const hTitle = document.getElementById('ep-header-left-title');
      if (hTitle && lastFinalHeaderTitleHTML) {
        hTitle.innerHTML = lastFinalHeaderTitleHTML;
      }
      // Prescript delivery complete: play complete_sound.wav chime
      playSoundEffect('complete');
      return;
    }

    const lineObj = parsed[curL];
    const el = document.getElementById(`ptl-${curL}`);

    if (curC < lineObj.text.length) {
      const char = lineObj.text[curC];
      curC++;
      const currentSub = lineObj.text.substring(0, curC);
      if (el) el.innerHTML = `${lineObj.prefix}${currentSub}<span class="ep-cursor"></span>`;

      // Subtle mechanical click every few characters for tactile typewriter presence
      if (curC % 2 === 0) playBeeperChirp('click');

      // Deliberate Prescript Punctuation Cadence (Natural reading pace)
      const baseDelay = typingSpeedMs;
      let stepDelay = baseDelay;
      if (char === '.' || char === '!' || char === '?') {
        stepDelay = baseDelay + 180;
      } else if (char === ',' || char === ';' || char === ':') {
        stepDelay = baseDelay + 110;
      } else if (char === ' ') {
        stepDelay = Math.max(12, baseDelay - 6);
      }

      typingTimer = setTimeout(typeStep, stepDelay);
    } else {
      // Line finished, affix suffix, carriage return delay
      if (el) el.innerHTML = `${lineObj.prefix}${lineObj.text}${lineObj.suffix}`;
      curL++;
      curC = 0;
      typingTimer = setTimeout(typeStep, typingSpeedMs + 120);
    }
  }

  typeStep();
}

