// ==============================================================================
const SCRAMBLE_CHARS = "ABCDEF@HIJ_LM%OPQR^WX#YZa#b+cdefgh*iqrxyz0123456789";
const NUM_SCRAMBLE_CHARS = SCRAMBLE_CHARS.length;

function getRandomCipherChar() {
  return SCRAMBLE_CHARS[Math.floor(Math.random() * NUM_SCRAMBLE_CHARS)];
}

let animationEnabled = true;
let isDrawing = false;
let typingTimer = null;
let lastRenderedPageData = null;
let lastRenderedAlignClass = 'content-left';
let lastFinalHeaderTitleHTML = '';

// Speed slider controls reveal delay in milliseconds per character
let typingSpeedMs = 24;

function updateTypingSpeedFromSlider(val) {
  typingSpeedMs = parseInt(val, 10) || 24;
  const label = document.getElementById('speed-label');
  if (label) label.textContent = `${typingSpeedMs}ms`;
}

function toggleAnimation() {
  animationEnabled = !animationEnabled;
  const btn = document.getElementById('btn-anim');
  if (btn) {
    btn.textContent = animationEnabled ? '📜 Anim: ON' : '⚡ Anim: OFF';
    btn.classList.toggle('active', animationEnabled);
  }
  playSoundEffect('complete');
}

