  if (typingTimer) {
    clearTimeout(typingTimer);
    typingTimer = null;
  }
  isDrawing = false;
  const led = document.querySelector('.beeper-led');
  if (led) led.classList.remove('drawing');
}

function parseDecoratedLine(lineItem) {
  const rawHtml = (typeof lineItem === 'object' && lineItem !== null) ? lineItem.html : lineItem;
  const align = (typeof lineItem === 'object' && lineItem !== null) ? (lineItem.align || 'line-left') : 'line-left';
  let prefix = '';
  let suffix = '';
  let text = rawHtml || '';

  const openTag = text.match(/^(<span class="ep-qmark ep-qmark-open"[^>]*>“<\/span>)/);
  if (openTag) {
    prefix = openTag[1];
    text = text.substring(openTag[0].length);
  }

  const closeTag = text.match(/(<span class="ep-qmark ep-qmark-close"[^>]*>”<\/span>|<span class="ep-ellipsis-cue"[^>]*>\.\.\.<\/span>)$/);
  if (closeTag) {
    suffix = closeTag[1];
    text = text.substring(0, text.length - closeTag[0].length);
  }

  return { prefix, text, suffix, align };
}

function runPrescriptTypewriter(activePage, alignClass) {
  stopDrawingAnimation();
  const container = document.getElementById('ep-viewport');
  if (!container) return;

  const headerTitleEl = document.getElementById('ep-header-left-title');
  if (headerTitleEl) {
    headerTitleEl.innerHTML = `<span class="ep-transmitting-badge">📡 // RECEIVING DIRECTIVE //</span>`;
  }

  const parsed = activePage.lines.map(parseDecoratedLine);
  container.innerHTML = `
    <div class="ep-content ${alignClass}">
      ${parsed.map((pl, i) => `<div class="ep-text-line ${pl.align}" id="ptl-${i}"></div>`).join('')}
    </div>
  `;

  isDrawing = true;
  const led = document.querySelector('.beeper-led');
  if (led) led.classList.add('drawing');

  let scrambleFramesLeft = 10;
  let revealLine = 0;
  let revealChar = 0;

  function renderFrame() {
    if (!isDrawing) return;

    // PHASE 0: Full Initial Cipher Scramble (Index Loom Frequency Tuning)
    if (scrambleFramesLeft > 0) {
      scrambleFramesLeft--;
      parsed.forEach((pl, lIdx) => {
        const el = document.getElementById(`ptl-${lIdx}`);
        if (!el) return;
        let scrambledText = '';
        for (let c = 0; c < pl.text.length; c++) {
          scrambledText += (pl.text[c] === ' ') ? ' ' : getRandomCipherChar();
        }
        el.innerHTML = `${pl.prefix}${scrambledText}`;
      });

      if (scrambleFramesLeft % 2 === 0) playBeeperChirp('click');
      typingTimer = setTimeout(renderFrame, 26);
      return;
    }

    // PHASE 1: Sequential Cipher Decoding Reveal (Left-to-Right, Line-by-Line)
    if (revealLine >= parsed.length) {
      // Animation completely finished
      isDrawing = false;
      if (led) led.classList.remove('drawing');

      parsed.forEach((pl, lIdx) => {
        const el = document.getElementById(`ptl-${lIdx}`);
        if (el) el.innerHTML = `${pl.prefix}${pl.text}${pl.suffix}`;
      });

      const hTitle = document.getElementById('ep-header-left-title');
      if (hTitle && lastFinalHeaderTitleHTML) {
        hTitle.innerHTML = lastFinalHeaderTitleHTML;
      }

      // Play complete_sound.wav once when text is fully displayed!
      playSoundEffect('complete');
      return;
    }

    // Render current state: revealed text + active cursor + scrambling tail
    parsed.forEach((pl, lIdx) => {
      const el = document.getElementById(`ptl-${lIdx}`);
      if (!el) return;

      if (lIdx < revealLine) {
        el.innerHTML = `${pl.prefix}${pl.text}${pl.suffix}`;
      } else if (lIdx === revealLine) {
        const revealedSub = pl.text.substring(0, revealChar);
        let tailScramble = '';
        for (let c = revealChar; c < pl.text.length; c++) {
          tailScramble += (pl.text[c] === ' ') ? ' ' : getRandomCipherChar();
        }
        el.innerHTML = `${pl.prefix}${revealedSub}<span class="ep-cursor"></span>${tailScramble}`;
      } else {
        let futureScramble = '';
        for (let c = 0; c < pl.text.length; c++) {
          futureScramble += (pl.text[c] === ' ') ? ' ' : getRandomCipherChar();
        }
        el.innerHTML = `${pl.prefix}${futureScramble}`;
      }
    });

    if (revealChar % 2 === 0) playBeeperChirp('click');

    const activeLineObj = parsed[revealLine];
    const revealedChar = activeLineObj.text[revealChar] || '';
    revealChar++;

    if (revealChar >= activeLineObj.text.length) {
      revealLine++;
      revealChar = 0;
      typingTimer = setTimeout(renderFrame, Math.max(16, typingSpeedMs + 40));
    } else {
      let delay = typingSpeedMs;
      if (revealedChar === '.' || revealedChar === '!' || revealedChar === '?') delay += 75;
      else if (revealedChar === ',' || revealedChar === ';') delay += 45;
      typingTimer = setTimeout(renderFrame, delay);
    }
  }

  renderFrame();
}

