/* 4-LINE DISCRETE FRAMEBUFFER VIEWPORT (ZERO SCROLLBAR // 4 LINES MAX) */
.ep-viewport {
  flex: 1;
  min-height: 0;
  overflow: hidden; /* Strict zero overflow */
  padding: 6px 14px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  user-select: text;
}

/* 4-Line Content Box */
.ep-content {
  font-family: var(--screen-font, "JetBrains Mono", monospace);
  font-size: var(--screen-font-size, 13px);
  line-height: 1.52;
  font-style: italic;
  color: #ffffff;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ep-content.content-justify {
  text-align: justify !important;
  text-justify: inter-word !important;
  hyphens: auto;
}
.ep-content.content-justify .ep-text-line.line-justify {
  text-align: justify !important;
  text-align-last: justify !important;
}
.ep-content.content-justify .ep-text-line.line-left,
.ep-content.content-left .ep-text-line {
  text-align: left !important;
  text-align-last: left !important;
}

.ep-text-line {
  min-height: 1.5em;
  line-height: 1.5;
  white-space: nowrap;
  overflow: hidden;
  display: block;
}

.ep-ellipsis-cue {
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.08em;
  display: inline;
  white-space: nowrap;
}

