function runPrescriptTypewriter(activePage, alignClass) {
  stopDrawingAnimation();
  stopGapChimeScheduler();
  const container = document.getElementById('ep-viewport');
  if (!container) return;

  const headerTitleEl = document.getElementById('ep-header-left-title');
  if (headerTitleEl) {
    headerTitleEl.innerHTML = `<span class="ep-transmitting-badge">📡 // RECEIVING DIRECTIVE //</span>`;
  }

  // 1. Kick off Prescript audio cadence: draw_sound immediately, then recurring complete_sound chimes to fill the gap
  playSoundEffect('draw');
  startGapChimeScheduler();

  const parsed = activePage.lines.map(parseDecoratedLine);
  const maxChars = getCharsPerLine(currentPresetKey);
  const MAX_LINES = 4;

  // 2. Initialize 4-Line Grid of Pure Chaos:
  // Every single spot in the content box is populated with random garbage text (including spaces!)
  const grid = [];
  for (let r = 0; r < MAX_LINES; r++) {
    const rowCells = [];
    const pl = parsed[r] || { prefix: '', text: '', suffix: '', align: 'line-left' };
    // Target line padded with spaces up to maxChars: <space> is also a real character
    const paddedTarget = (pl.text || '').padEnd(maxChars, ' ');

    for (let c = 0; c < maxChars; c++) {
      const targetChar = paddedTarget[c];
      // Chaos lifetime: each cell transforms a random number of times at slightly different speeds (Entropy)
      const minSteps = 10;
      const maxSteps = 34;
      const mutationsLeft = Math.floor(minSteps + Math.random() * (maxSteps - minSteps));
      // Speed variance per cell: similar speed, but not the same speed
      const jitterSpeed = Math.max(12, Math.floor(entropySpeedMs * (0.75 + Math.random() * 0.5)));

      rowCells.push({
        r: r,
        c: c,
        targetChar: targetChar,
        currentChar: getRandomCipherChar(),
        mutationsLeft: mutationsLeft,
        interval: jitterSpeed,
        nextTick: performance.now() + Math.random() * 30,
        isLocked: false
      });
    }
    grid.push(rowCells);
  }

  container.innerHTML = `
    <div class="ep-content ${alignClass}">
      ${[0, 1, 2, 3].map(i => `<div class="ep-text-line ${(parsed[i] && parsed[i].align) || 'line-left'}" id="ptl-${i}"></div>`).join('')}
    </div>
  `;

  isDrawing = true;
  const led = document.querySelector('.beeper-led');
  if (led) led.classList.add('drawing');

  let lastClickTick = 0;

  function entropyStep() {
    if (!isDrawing) return;

    const now = performance.now();
    let allLocked = true;

    for (let r = 0; r < MAX_LINES; r++) {
      let lineChars = '';
      const pl = parsed[r] || { prefix: '', text: '', suffix: '' };

      for (let c = 0; c < maxChars; c++) {
        const cell = grid[r][c];
        if (!cell.isLocked) {
          allLocked = false;
          if (now >= cell.nextTick) {
            cell.mutationsLeft--;
            cell.nextTick = now + cell.interval;
            if (cell.mutationsLeft <= 0) {
              // Cell crystallizes into its real content (letter, punctuation, or space)!
              cell.currentChar = cell.targetChar;
              cell.isLocked = true;
            } else {
              // Remains in entropy mutation
              cell.currentChar = getRandomCipherChar();
            }
          }
        }
        lineChars += cell.currentChar;
      }

      const el = document.getElementById(`ptl-${r}`);
      if (el) {
        el.innerHTML = `${pl.prefix}${lineChars}`;
      }
    }

    if (now - lastClickTick > 70) {
      playBeeperChirp('click');
      lastClickTick = now;
    }

    if (allLocked) {
      // Chaos completely resolved into Content!
      isDrawing = false;
      stopGapChimeScheduler();
      if (led) led.classList.remove('drawing');

      // Render clean final HTML with proper prefixes, suffixes, quotation marks, and line justification classes
      container.innerHTML = `
        <div class="ep-content ${alignClass}">
          ${parsed.map(pl => `<div class="ep-text-line ${pl.align}">${pl.prefix}${pl.text}${pl.suffix}</div>`).join('')}
        </div>
      `;

      const hTitle = document.getElementById('ep-header-left-title');
      if (hTitle && lastFinalHeaderTitleHTML) {
        hTitle.innerHTML = lastFinalHeaderTitleHTML;
      }

      // Final decree seal: play complete_sound.wav once when text is fully displayed!
      playSoundEffect('complete');
      return;
    }

    typingTimer = requestAnimationFrame(entropyStep);
  }

  entropyStep();
}

function skipAnimation() {
  if (!isDrawing) return;
  stopDrawingAnimation();
  stopGapChimeScheduler();

  const headerTitleEl = document.getElementById('ep-header-left-title');
  if (headerTitleEl && lastFinalHeaderTitleHTML) {
    headerTitleEl.innerHTML = lastFinalHeaderTitleHTML;
  }

  const container = document.getElementById('ep-viewport');
  if (container && lastRenderedPageData) {
    container.innerHTML = `
      <div class="ep-content ${lastRenderedAlignClass}">
        ${lastRenderedPageData.lines.map(line => {
          const htmlStr = (typeof line === 'object' && line !== null) ? line.html : line;
          const alignCls = (typeof line === 'object' && line !== null) ? (line.align || 'line-left') : 'line-left';
          return `<div class="ep-text-line ${alignCls}">${htmlStr}</div>`;
        }).join('')}
      </div>
    `;
  }
  playSoundEffect('complete');
}

// ==============================================================================
// 3. INITIALIZATION & DATA FETCHING
// ==============================================================================
async function init() {
  applyPreset('19', false);

  try {
    const [taxRes, qRes] = await Promise.all([
      fetch(`${API_BASE}/api/taxonomy`).then(r => r.json()).catch(() => null),
      fetch(`${API_BASE}/api/quotes/list`).then(r => r.json()).catch(() => null)
    ]);

    if (taxRes && qRes && qRes.length > 0) {
      availableSpecifics = taxRes.specifics || [];
      availableThemes = taxRes.themes || [];
      quotesList = qRes;
      document.getElementById('connection-status').innerHTML = '● LIVE API SYNCED';
      document.getElementById('connection-status').style.color = '#38bdf8';
    } else {
      useFallbackData();
    }

