// Helper to justify a list of words across targetWidth in monospace text
function justifyWordsToWidth(words, targetWidth) {
  if (!words || words.length === 0) return ' '.repeat(targetWidth);
  if (words.length === 1) return words[0].padEnd(targetWidth, ' ');
  const totalLetters = words.reduce((acc, w) => acc + w.length, 0);
  const gaps = words.length - 1;
  const totalSpaces = targetWidth - totalLetters;
  if (totalSpaces < gaps) return words.join(' ').padEnd(targetWidth, ' ');
  const spacesPerGap = Math.floor(totalSpaces / gaps);
  const extraSpaces = totalSpaces % gaps;
  let res = '';
  for (let i = 0; i < words.length; i++) {
    res += words[i];
    if (i < gaps) {
      const spCount = spacesPerGap + (i < extraSpaces ? 1 : 0);
      res += ' '.repeat(spCount);
    }
  }
  return res;
}

