isDrawing = true;
const led = document.querySelector('.beeper-led');
if (led) led.classList.add('drawing');

let lastClickTick = 0;

function entropyStep() {
  if (!isDrawing) return;

  const now = performance.now();
  let allLocked = true;

  for (let r = 0; r < MAX_LINES; r++) {
    let lineChars = '';
    const pl = parsed[r];

    for (let c = 0; c < maxChars; c++) {
      const cell = grid[r][c];
      if (!cell.isLocked) {
        allLocked = false;
        if (now >= cell.nextTick) {
          cell.mutationsLeft--;
          cell.nextTick = now + cell.interval;
          if (cell.mutationsLeft <= 0) {
            // Cell crystallizes into its real content (letter, punctuation, or space)!
            cell.currentChar = cell.targetChar;
            cell.isLocked = true;
          } else {
            // Remains in entropy mutation
            cell.currentChar = getRandomCipherChar();
          }
        }
      }
      lineChars += cell.currentChar;
    }

    const el = document.getElementById(`ptl-${r}`);
    if (el) {
      el.innerHTML = `${pl.prefix}${lineChars}`;
    }
  }

  if (now - lastClickTick > 70) {
    playBeeperChirp('click');
    lastClickTick = now;
  }

  if (allLocked) {
    // Chaos completely resolved into Content!
    isDrawing = false;
    stopGapChimeScheduler();
    if (led) led.classList.remove('drawing');

    // Render clean final HTML with proper prefixes, suffixes, quotation marks, and line justification classes
    container.innerHTML = `
      <div class="ep-content ${alignClass}">
        ${parsed.map(pl => {
          if (pl.isBlank) {
            return `<div class="ep-text-line line-left">&nbsp;</div>`;
          }
          return `<div class="ep-text-line ${pl.align}">${pl.prefix}${pl.text}${pl.suffix}</div>`;
        }).join('')}
      </div>
    `;

    const hTitle = document.getElementById('ep-header-left-title');
    if (hTitle && lastFinalHeaderTitleHTML) {
      hTitle.innerHTML = lastFinalHeaderTitleHTML;
    }

    // Final decree seal: play complete_sound.wav once when text is fully displayed!
    playSoundEffect('complete');
    return;
  }

  typingTimer = requestAnimationFrame(entropyStep);
}

