const headerTitleEl = document.getElementById('ep-header-left-title');
if (headerTitleEl) {
  headerTitleEl.innerHTML = `<span class="ep-transmitting-badge">// Receiving prescript...</span>`;
}

// 1. Kick off Prescript audio cadence: draw_sound immediately, then recurring complete_sound chimes to fill the gap
playSoundEffect('draw');
startGapChimeScheduler();

// Map lines to fixed 4 physical rows:
// 1 line => row 2; 2 lines => row 2 & 3; 3 lines => row 1, 2, 3; 4+ => row 1, 2, 3, 4
const fourRows = mapLinesToFourRows(activePage.lines);
const parsed = fourRows.map(parseDecoratedLine);
const maxChars = getCharsPerLine(currentPresetKey);
const MAX_LINES = 4;

// 2. Initialize 4-Line Grid of Pure Chaos:
// Every single spot in the content box is populated with random garbage text (including spaces!)
const grid = [];
for (let r = 0; r < MAX_LINES; r++) {
  const rowCells = [];
  const pl = parsed[r];
  // Target line padded with spaces up to maxChars: <space> is also a real character
  const targetText = pl.isBlank ? '' : (pl.text || '');
  const paddedTarget = targetText.padEnd(maxChars, ' ');

  for (let c = 0; c < maxChars; c++) {
    const targetChar = paddedTarget[c];
    // Measured lifetime: smooth, calm crystallization without frantic flickering
    const minSteps = 12;
    const maxSteps = 26;
    const mutationsLeft = Math.floor(minSteps + Math.random() * (maxSteps - minSteps));
    // Calibrated speed: similar speed, subtle organic variance
    const jitterSpeed = Math.max(16, Math.floor(entropySpeedMs * (0.85 + Math.random() * 0.3)));

    rowCells.push({
      r: r,
      c: c,
      targetChar: targetChar,
      currentChar: getRandomCipherChar(),
      mutationsLeft: mutationsLeft,
      interval: jitterSpeed,
      nextTick: performance.now() + Math.random() * 30,
      isLocked: false
    });
  }
  grid.push(rowCells);
}

container.innerHTML = `
  <div class="ep-content ${alignClass}">
    ${[0, 1, 2, 3].map(i => `<div class="ep-text-line ${parsed[i].align || 'line-left'}" id="ptl-${i}"></div>`).join('')}
  </div>
`;

isDrawing = true;
const led = document.querySelector('.beeper-led');
if (led) led.classList.add('drawing');

let lastClickTick = 0;

function entropyStep() {
  if (!isDrawing) return;

  const now = performance.now();
  let allLocked = true;

  for (let r = 0; r < MAX_LINES; r++) {
    let lineChars = '';
    const pl = parsed[r];

    for (let c = 0; c < maxChars; c++) {
      const cell = grid[r][c];
      if (!cell.isLocked) {
        allLocked = false;
        if (now >= cell.nextTick) {
          cell.mutationsLeft--;
          cell.nextTick = now + cell.interval;
          if (cell.mutationsLeft <= 0) {
            // Cell crystallizes into its real content (letter, punctuation, or space)!
            cell.currentChar = cell.targetChar;
            cell.isLocked = true;
          } else {
            // Remains in entropy mutation
            cell.currentChar = getRandomCipherChar();
          }
        }
      }
      lineChars += cell.currentChar;
    }

    const el = document.getElementById(`ptl-${r}`);
    if (el) {
      el.innerHTML = `${pl.prefix}${lineChars}`;
    }
  }

  if (now - lastClickTick > 70) {
    playBeeperChirp('click');
    lastClickTick = now;
  }

  if (allLocked) {
    // Chaos completely resolved into Content!
    isDrawing = false;
    stopGapChimeScheduler();
    if (led) led.classList.remove('drawing');

    // Render clean final HTML with proper prefixes, suffixes, quotation marks, and line justification classes
    container.innerHTML = `
      <div class="ep-content ${alignClass}">
        ${parsed.map(pl => {
          if (pl.isBlank) {
            return `<div class="ep-text-line line-left">&nbsp;</div>`;
          }
          return `<div class="ep-text-line ${pl.align}">${pl.prefix}${pl.text}${pl.suffix}</div>`;
        }).join('')}
      </div>
    `;

    const hTitle = document.getElementById('ep-header-left-title');
    if (hTitle && lastFinalHeaderTitleHTML) {
      hTitle.innerHTML = lastFinalHeaderTitleHTML;
    }

    // Final decree seal: play complete_sound.wav once when text is fully displayed!
    playSoundEffect('complete');
    return;
  }

