let delayDrawToCompleteMs = 650;
let delayBetweenCompletesMs = 450;
let gapChimeTimer = null;

function updateDrawDelay(val) {
  delayDrawToCompleteMs = parseInt(val, 10) || 650;
  const label = document.getElementById('draw-delay-label');
