function updateChimeInterval(val) {
  delayBetweenCompletesMs = parseInt(val, 10) || 450;
  const label = document.getElementById('interval-delay-label');
  if (label) label.textContent = `${delayBetweenCompletesMs}ms`;
}

function stopGapChimeScheduler() {
  if (gapChimeTimer) {
    clearTimeout(gapChimeTimer);
    gapChimeTimer = null;
  }
}

// Schedule complete_sound.wav chimes to fill the gap until text resolves
function startGapChimeScheduler() {
  stopGapChimeScheduler();
  if (!soundEnabled || !userHasInteracted) return;

  // 1. Initial delay between draw_sound.wav and the first complete_sound chime
  gapChimeTimer = setTimeout(function chimeLoop() {
    if (!isDrawing) return;
    playSoundEffect('complete');

    // 2. Subsequent delay between complete_sound chimes to fill the gap
    gapChimeTimer = setTimeout(chimeLoop, delayBetweenCompletesMs);
  }, delayDrawToCompleteMs);
}

