      ${[0, 1, 2, 3].map(i => `<div class="ep-text-line ${fourRows[i].align || 'line-left'}" id="ptl-${i}"></div>`).join('')}
    </div>
  `;

  isDrawing = true;
  const led = document.querySelector('.beeper-led');
  if (led) led.classList.add('drawing');

  let lastClickTick = 0;

  function entropyStep() {
    if (!isDrawing) return;

    const now = performance.now();
    const elapsed = now - startTime;
    let allLocked = true;

    for (let r = 0; r < MAX_LINES; r++) {
      let lineHtml = '';

      for (let c = 0; c < maxChars; c++) {
        const cell = grid[r][c];

        if (!cell.isLocked) {
          if (elapsed >= cell.lifespanMs) {
            // Lifespan expired: locks into its final character!
            cell.isLocked = true;
            cell.currentChar = cell.targetChar;
          } else {
            allLocked = false;
            if (elapsed >= cell.nextScramble) {
              cell.currentChar = getRandomCipherChar();
              cell.nextScramble = elapsed + 35 + Math.random() * 25;
            }
          }
        }

        if (cell.isLocked) {
          if (cell.targetChar === ' ') {
            lineHtml += `<span class="ep-c ep-space"> </span>`;
          } else if (cell.targetChar === '“' || cell.targetChar === '”') {
            lineHtml += `<span class="ep-c ep-qmark" style="color:${accentColor};">${cell.targetChar}</span>`;
          } else if (cell.targetChar === '.') {
            lineHtml += `<span class="ep-c ep-ellipsis-cue" style="color:${accentColor};">.</span>`;
          } else {
            lineHtml += `<span class="ep-c">${cell.targetChar}</span>`;
          }
        } else {
          lineHtml += `<span class="ep-c ep-scramble">${cell.currentChar}</span>`;
        }
      }

      const el = document.getElementById(`ptl-${r}`);
      if (el) {
        el.innerHTML = lineHtml;
      }
    }

    if (now - lastClickTick > 75) {
      playBeeperChirp('click');
      lastClickTick = now;
    }

    if (allLocked) {
      // Chaos completely resolved into Content!
      isDrawing = false;
      stopGapChimeScheduler();
      if (led) led.classList.remove('drawing');

      // Render clean final HTML
      container.innerHTML = `
        <div class="ep-content ${alignClass}">
          ${fourRows.map((pl, rIdx) => {
            if (pl.isBlank) {
              return `<div class="ep-text-line line-left">&nbsp;</div>`;
            }
            const formattedHtml = pl.text.split('').map(ch => {
              if (ch === '“' || ch === '”') return `<span class="ep-c ep-qmark" style="color:${accentColor};">${ch}</span>`;
              if (ch === '.') return `<span class="ep-c ep-ellipsis-cue" style="color:${accentColor};">.</span>`;
              if (ch === ' ') return `<span class="ep-c ep-space"> </span>`;
              return `<span class="ep-c">${ch}</span>`;
            }).join('');
            return `<div class="ep-text-line ${pl.align}">${formattedHtml}</div>`;
          }).join('')}
        </div>
      `;

      const hTitle = document.getElementById('ep-header-left-title');
      if (hTitle && lastFinalHeaderTitleHTML) {
        hTitle.innerHTML = lastFinalHeaderTitleHTML;
      }

      // Final decree seal: play complete_sound.wav once when text is fully displayed!
      playSoundEffect('complete');
      return;
    }

    typingTimer = requestAnimationFrame(entropyStep);
  }

  entropyStep();
}

function skipAnimation() {
  if (!isDrawing) return;
  stopDrawingAnimation();
  stopGapChimeScheduler();

  const headerTitleEl = document.getElementById('ep-header-left-title');
  if (headerTitleEl && lastFinalHeaderTitleHTML) {
    headerTitleEl.innerHTML = lastFinalHeaderTitleHTML;
  }

  const container = document.getElementById('ep-viewport');
  if (container && lastRenderedPageData) {
    const fourRows = mapLinesToFourRows(lastRenderedPageData.lines);
    const accentColor = (typeof activeAccentColor !== 'undefined' && activeAccentColor) ? activeAccentColor : '#38bdf8';
    container.innerHTML = `
      <div class="ep-content ${lastRenderedAlignClass}">
        ${fourRows.map(line => {
          if (line.isBlank) return `<div class="ep-text-line line-left">&nbsp;</div>`;
          const formattedHtml = (line.text || '').split('').map(ch => {
            if (ch === '“' || ch === '”') return `<span class="ep-c ep-qmark" style="color:${accentColor};">${ch}</span>`;
            if (ch === '.') return `<span class="ep-c ep-ellipsis-cue" style="color:${accentColor};">.</span>`;
            if (ch === ' ') return `<span class="ep-c ep-space"> </span>`;
            return `<span class="ep-c">${ch}</span>`;
          }).join('');
          return `<div class="ep-text-line ${line.align || 'line-left'}">${formattedHtml}</div>`;
        }).join('')}
      </div>
    `;
  }
  playSoundEffect('complete');
}

