  let suffix = '';
  let text = rawHtml || '';

  if (isBlank) {
    return { prefix: '', text: '', suffix: '', align: 'line-left', isBlank: true };
  }

  const openTag = text.match(/^(<span class="ep-qmark ep-qmark-open"[^>]*>“<\/span>)/);
  if (openTag) {
    prefix = openTag[1];
    text = text.substring(openTag[0].length);
  }

  const closeTag = text.match(/(<span class="ep-qmark ep-qmark-close"[^>]*>”<\/span>|<span class="ep-ellipsis-cue"[^>]*>\.\.\.<\/span>)$/);
  if (closeTag) {
    suffix = closeTag[1];
    text = text.substring(0, text.length - closeTag[0].length);
  }

  return { prefix, text, suffix, align, isBlank: false };
}

function runPrescriptTypewriter(activePage, alignClass) {
  stopDrawingAnimation();
  stopGapChimeScheduler();
  const container = document.getElementById('ep-viewport');
  if (!container) return;

  const headerTitleEl = document.getElementById('ep-header-left-title');
  if (headerTitleEl) {
    headerTitleEl.innerHTML = `<span class="ep-transmitting-badge">// Receiving prescript...</span>`;
  }

  // 1. Kick off Prescript audio cadence: draw_sound immediately, then recurring complete_sound chimes to fill the gap
  playSoundEffect('draw');
  startGapChimeScheduler();

  // Map lines to fixed 4 physical rows:
  // 1 line => row 2; 2 lines => row 2 & 3; 3 lines => row 1, 2, 3; 4+ => row 1, 2, 3, 4
  const fourRows = mapLinesToFourRows(activePage.lines);
  const maxChars = getCharsPerLine(currentPresetKey);
  const MAX_LINES = 4;
  const accentColor = (typeof activeAccentColor !== 'undefined' && activeAccentColor) ? activeAccentColor : '#38bdf8';

  // 2. Initialize 4-Line Grid of Pure Chaos:
  // Every single spot in the content box is populated with random garbage text (including spaces!)
  // Each character position has an independent random lifespan (like fixing random pixels on a chaotic canvas)
  const totalDurationMs = Math.max(900, entropySpeedMs * 35);
