const maxChars = getCharsPerLine(currentPresetKey);
const MAX_LINES = 4;
const accentColor = (typeof activeAccentColor !== 'undefined' && activeAccentColor) ? activeAccentColor : '#38bdf8';

// 2. Initialize 4-Line Grid of Pure Chaos:
// Every single spot in the content box is populated with random garbage text (including spaces!)
// Each character position has an independent random lifespan (like fixing random pixels on a chaotic canvas)
const totalDurationMs = Math.max(900, entropySpeedMs * 35);
const startTime = performance.now();
const grid = [];

for (let r = 0; r < MAX_LINES; r++) {
  const rowCells = [];
  const pl = fourRows[r];
  // Target line padded with spaces up to maxChars: <space> is also a real character
  const rawText = pl.isBlank ? '' : (pl.text || '');
  const paddedTarget = rawText.padEnd(maxChars, ' ');

  for (let c = 0; c < maxChars; c++) {
    const targetChar = paddedTarget[c];
    // Purely independent random lifespan across the canvas duration (independent from position!)
    const lifespanMs = Math.random() * totalDurationMs;

    rowCells.push({
      r: r,
      c: c,
      targetChar: targetChar,
      currentChar: getRandomCipherChar(),
      lifespanMs: lifespanMs,
      nextScramble: Math.random() * 40,
      isLocked: false
    });
  }
  grid.push(rowCells);
}

container.innerHTML = `
  <div class="ep-content animating ${alignClass}">
    ${[0, 1, 2, 3].map(i => `<div class="ep-text-line ${fourRows[i].align || 'line-left'}" id="ptl-${i}"></div>`).join('')}
  </div>
`;

isDrawing = true;
const led = document.querySelector('.beeper-led');
if (led) led.classList.add('drawing');

let lastClickTick = 0;

function entropyStep() {
  if (!isDrawing) return;

  const now = performance.now();
  const elapsed = now - startTime;
  let allLocked = true;

  for (let r = 0; r < MAX_LINES; r++) {
    let lineHtml = '';

    for (let c = 0; c < maxChars; c++) {
      const cell = grid[r][c];

      if (!cell.isLocked) {
        if (elapsed >= cell.lifespanMs) {
          // Lifespan expired: locks into its final character!
          cell.isLocked = true;
          cell.currentChar = cell.targetChar;
        } else {
          allLocked = false;
          if (elapsed >= cell.nextScramble) {
            cell.currentChar = getRandomCipherChar();
            cell.nextScramble = elapsed + 35 + Math.random() * 25;
          }
        }
      }

      if (cell.isLocked) {
        if (cell.targetChar === ' ') {
          lineHtml += `<span class="ep-c ep-space"> </span>`;
        } else if (cell.targetChar === '“' || cell.targetChar === '”') {
          lineHtml += `<span class="ep-c ep-qmark" style="color:${accentColor};">${cell.targetChar}</span>`;
        } else if (cell.targetChar === '.') {
          lineHtml += `<span class="ep-c ep-ellipsis-cue" style="color:${accentColor};">.</span>`;
        } else {
          lineHtml += `<span class="ep-c">${cell.targetChar}</span>`;
        }
      } else {
        lineHtml += `<span class="ep-c ep-scramble">${cell.currentChar}</span>`;
      }
    }

