/* Physical Industrial Bezel */
.beeper-outer-case {
  position: relative;
  background: #111111;
  border: 2px solid #282828;
  border-radius: 14px;
  padding: 18px 24px 22px;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.95), inset 0 1px 1px rgba(255, 255, 255, 0.1), 0 0 0 1px #000;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  transition: all 0.2s ease;
}

/* Metallic Chassis Screws */
.screw {
  position: absolute;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #282828;
  border: 1px solid #1a1a1a;
  box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.15);
}
.screw::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 1px;
  width: 3px;
  height: 1px;
  background: #444;
}
.screw.top-left { top: 7px; left: 8px; }
.screw.top-right { top: 7px; right: 8px; }
.screw.bottom-left { bottom: 7px; left: 8px; }
.screw.bottom-right { bottom: 7px; right: 8px; }

/* Silkscreen Markings on Bezel */
.bezel-silkscreen-top {
  font-size: 8px;
  font-weight: 700;
  color: #4a4a4a;
  letter-spacing: 0.18em;
  margin-bottom: 8px;
  text-transform: uppercase;
  user-select: none;
}

.bezel-silkscreen-bottom {
  display: flex;
  justify-content: space-between;
  width: 100%;
  font-size: 7px;
  font-weight: 700;
  color: #3e3e3e;
  letter-spacing: 0.12em;
  margin-top: 10px;
  text-transform: uppercase;
  user-select: none;
}

/* ==========================================================================
   THE SCREEN FRAMEBUFFER (LOCKED ASPECT RATIO & RESOLUTION)
   ========================================================================== */
.epaper-screen {
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  border-radius: 4px;
  border: 2px solid #000000;
  box-shadow: inset 0 0 14px rgba(0, 0, 0, 0.8), 0 0 0 1px #222;

