function playBeeperChirp(type = 'chirp') {
  if (!soundEnabled || !userHasInteracted) return;
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') {
      audioCtx.resume().catch(() => {});
      return;
    }

    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);

    const now = audioCtx.currentTime;
    if (type === 'chirp') {
      osc.type = 'square';
      osc.frequency.setValueAtTime(1760, now);
      osc.frequency.setValueAtTime(2637, now + 0.04);
      gain.gain.setValueAtTime(0.04, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
      osc.start(now);
      osc.stop(now + 0.1);
    } else if (type === 'click') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(987, now);
      gain.gain.setValueAtTime(0.03, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);
      osc.start(now);
      osc.stop(now + 0.03);
    }
  } catch (e) {
    // AudioContext silent fallback
  }
}

function playSoundEffect(type) {
  if (!soundEnabled || !userHasInteracted) return;
  try {
    if (type === 'draw') {
      soundDraw.currentTime = 0;
      const p = soundDraw.play();
      if (p && p.catch) p.catch(() => playBeeperChirp('chirp'));
    } else if (type === 'complete') {
      soundComplete.currentTime = 0;
      const p = soundComplete.play();
      if (p && p.catch) p.catch(() => playBeeperChirp('click'));
    }
  } catch (e) {
    playBeeperChirp(type === 'draw' ? 'chirp' : 'click');
  }
}

// Prescript Dual Audio Delays (Configurable via Sliders)
let delayDrawToCompleteMs = 650;
let delayBetweenCompletesMs = 450;
let gapChimeTimer = null;

function updateDrawDelay(val) {
  delayDrawToCompleteMs = parseInt(val, 10) || 650;
  const label = document.getElementById('draw-delay-label');
  if (label) label.textContent = `${delayDrawToCompleteMs}ms`;
}

function updateChimeInterval(val) {
  delayBetweenCompletesMs = parseInt(val, 10) || 450;
  const label = document.getElementById('interval-delay-label');
  if (label) label.textContent = `${delayBetweenCompletesMs}ms`;
}

function stopGapChimeScheduler() {
  if (gapChimeTimer) {
    clearTimeout(gapChimeTimer);
    gapChimeTimer = null;

