const headerTitleEl = document.getElementById('ep-header-left-title');
if (headerTitleEl) {
  headerTitleEl.innerHTML = `<span class="ep-transmitting-badge">// Receiving prescript...</span>`;
}

// 1. Kick off Prescript audio cadence: draw_sound immediately, then recurring complete_sound chimes to fill the gap
playSoundEffect('draw');
startGapChimeScheduler();

// Map lines to fixed 4 physical rows:
// 1 line => row 2; 2 lines => row 2 & 3; 3 lines => row 1, 2, 3; 4+ => row 1, 2, 3, 4
const fourRows = mapLinesToFourRows(activePage.lines);
const maxChars = getCharsPerLine(currentPresetKey);
const MAX_LINES = 4;
const accentColor = (typeof activeAccentColor !== 'undefined' && activeAccentColor) ? activeAccentColor : '#38bdf8';

// 2. Initialize Prescript Unboxing Placeholder Grid:
// Chaos characters ONLY appear where content characters (including <space>) exist!
// If content has 2 lines, chaos only appears on those 2 lines, matching their exact character lengths.
const totalDurationMs = Math.max(900, entropySpeedMs * 35);
const startTime = performance.now();
const grid = [];

for (let r = 0; r < MAX_LINES; r++) {
  const rowCells = [];
  const pl = fourRows[r];

  if (!pl.isBlank && pl.text) {
    const rawText = pl.text;
    const lineLen = rawText.length;

    for (let c = 0; c < lineLen; c++) {
      const targetChar = rawText[c];
      // Independent random lifespan across the canvas duration
      const lifespanMs = Math.random() * totalDurationMs;

      rowCells.push({
        r: r,
        c: c,
        targetChar: targetChar,
        currentChar: getRandomCipherChar(),
        lifespanMs: lifespanMs,
        nextScramble: Math.random() * 40,
        isLocked: false
      });
    }
  }

  grid.push(rowCells);
}

container.innerHTML = `
